{
  "schemaVersion": "0.2",
  "slug": "menu",
  "name": "Menu",
  "status": "experimental",
  "purpose": "Displays a list of actions or choices in a dropdown.",
  "scenarios": [
    "Show a user actions menu",
    "Show a filter menu",
    "Show a context menu trigger"
  ],
  "props": {
    "triggerLabel": {
      "type": "string",
      "required": true,
      "description": "Button that opens the menu."
    },
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of {label, onClick} items."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "open",
      "description": "Menu is visible."
    },
    {
      "name": "closed",
      "description": "Menu is hidden."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for navigation; use a link list.",
    "Do not hide disabled items without a reason."
  ],
  "a11y": {
    "role": "menu",
    "keyboard": [
      "Enter/Space opens",
      "Arrow keys navigate",
      "Esc closes"
    ],
    "focus": "Focus moves into the menu on open.",
    "labeling": "Trigger labels the menu.",
    "wcag": [
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Dropdown menu.",
    "breakpoints": {
      "compact": "Full width list.",
      "medium": "Fixed width list.",
      "large": "Fixed width list."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "menu",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "choose-action"
    ]
  }
}

import { PopoverPrimitive } from '@chameleon-ui/primitives'
import './styles.css'

export interface MenuItem {
  label: string
  onClick: () => void
}

export interface MenuProps {
  triggerLabel: string
  items: MenuItem[]
  className?: string
}

export function Menu({ triggerLabel, items, className }: MenuProps) {
  const classes = ['cu-menu', className].filter(Boolean).join(' ')
  return (
    <PopoverPrimitive.Root>
      <PopoverPrimitive.Trigger className="cu-menu__trigger">{triggerLabel}</PopoverPrimitive.Trigger>
      <PopoverPrimitive.Positioner>
        <PopoverPrimitive.Content className={classes} data-ai-role="menu" data-ai-state="open" data-ai-intent="choose-action" role="menu">
          <ul className="cu-menu__list">
            {items.map((item, index) => (
              <li className="cu-menu__item" key={index}>
                <button className="cu-menu__button" onClick={item.onClick} type="button" role="menuitem">
                  {item.label}
                </button>
              </li>
            ))}
          </ul>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Root>
  )
}

.cu-menu__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-menu {
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  box-shadow: var(--cu-shadow-md, 0 1px 3px color-mix(in srgb, var(--cu-color-background-inverse) 12%, transparent));
  z-index: 10;
  min-inline-size: 10rem;
}

.cu-menu__list {
  list-style: none;
  margin: 0;
  padding: var(--cu-space-1);
}

.cu-menu__item + .cu-menu__item {
  border-block-start: 1px solid var(--cu-color-border-default);
}

.cu-menu__button {
  display: flex;
  inline-size: 100%;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 0;
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.cu-menu__button:focus-visible {
  outline: 2px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
  border-radius: var(--cu-radius-sm);
}
